using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Xml.Linq;using V15Voice;
public static class Update145Tests {
 static int count;static string dir,root;static bool No(){return false;}static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);count++;Console.WriteLine("PASS "+name);}static void Reject(Action f,string name){try{f();}catch{Check(true,name);return;}throw new Exception("FAIL "+name);}
 static Wave Tone(double seconds,double amplitude=1000){return new Wave{Rate=24000,Samples=Enumerable.Range(0,(int)(seconds*24000)).Select(i=>(short)(amplitude*Math.Sin(i*2*Math.PI*220/24000))).ToArray()};}
 static void ImportReject(string src,string dst,double start,double length,string why){File.WriteAllText(dst,"KEEP");Reject(()=>UserVoices.Import(root,src,dst,start,length,No),why);Check(File.ReadAllText(dst)=="KEEP",why+" preserves existing reference");}
 public static void Main(string[] args){root=Path.GetFullPath(args[0]);dir=Path.Combine(Path.GetTempPath(),"V15_145_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);
  var o=new RenderOptions{GentleFit=true,MinSpeed=.8,MaxSpeed=1.6};Check(Tempo.Minimum(o)==.9&&Tempo.Maximum(o)==1.1,"Gentle fitting bounds remain ±10% at speed 1");o.BaseSpeed=1.2;Check(Math.Abs(Tempo.Minimum(o)-1.08)<.0001&&Math.Abs(Tempo.Maximum(o)-1.32)<.0001,"Gentle bounds follow chosen base speed");
  var engine=new FakeSpeech{Root=root,Seconds=3.55};o=new RenderOptions{GentleFit=true,MinSpeed=.9,MaxSpeed=1.3,Breathing=BreathMode.None,SlowShort=true};var cue=new Cue{Id=1,Start=0,End=3.3,Text="This is a longer sentence."};string original=Scripts.ToSrt(new List<Cue>{cue});string fit=Renderer.Render(new List<Cue>{cue},engine,o,Path.Combine(dir,"fit.wav"),(p,m)=>{});Check(cue.Speed>1&&cue.Speed<=1.1&&cue.Actual<=3.3,"Long cue fits inside gentle speed cap without regeneration");Check(engine.Calls==1&&Scripts.ToSrt(new List<Cue>{cue})==original&&FinalAudio.PcmFrames(fit)==79200,"Gentle fitting preserves all source timecodes and exact timeline length");
  engine.Seconds=1.7;cue=new Cue{Id=1,Start=0,End=3.3,Text="Short sentence."};Renderer.Render(new List<Cue>{cue},engine,o,Path.Combine(dir,"short.wav"),(p,m)=>{});Check(cue.Speed>=.9&&cue.Speed<1&&cue.Status.Contains("nghỉ dư"),"Very short cue slows gently and explicitly warns about remaining quiet time");
  o.Punctuation=PunctuationMode.Custom;cue=new Cue{Id=1,Start=0,End=3.3,Text="Short sentence."};Renderer.Render(new List<Cue>{cue},engine,o,Path.Combine(dir,"custom.wav"),(p,m)=>{});Check(cue.Speed<1&&cue.Speed>=.9,"Custom punctuation now supports gently slowing short cues");
  engine.Seconds=4;cue=new Cue{Id=1,Start=0,End=3.3,Text="Cannot fit gently."};Reject(()=>Renderer.Render(new List<Cue>{cue},engine,o,Path.Combine(dir,"over.wav"),(p,m)=>{}),"Unfit gentle cue rejected instead of clipping or exceeding cap");Check(cue.Speed<=1.1&&!File.Exists(Path.Combine(dir,"over.wav")),"No incomplete master WAV published");o.GentleFit=false;o.MaxSpeed=1.3;Renderer.Render(new List<Cue>{cue},engine,o,Path.Combine(dir,"custom-bound.wav"),(p,m)=>{});Check(cue.Speed>1.1&&cue.Speed<=1.3,"Explicit custom bounds can fit a cue beyond gentle range");
  var cache=new SpeechCache();engine=new FakeSpeech{Root=root,Seconds=.3,PreviewCache=cache,VoiceName="Voice A",ReferenceText="exact text",ReferencePath=Path.Combine(dir,"ref.wav")};Tone(1).Write(engine.ReferencePath);engine.GetSpeech("Hello",1,"");engine.GetSpeech("Hello",1,"");Check(engine.Calls==1,"Same voice, words and speed reuse measured audio");engine.ReferenceText="different";engine.GetSpeech("Hello",1,"");engine.DeviceMode="cpu";engine.GetSpeech("Hello",1,"");engine.VoiceName="Voice B";engine.GetSpeech("Hello",1,"");engine.GetSpeech("Hello",1.1,"");Tone(2).Write(engine.ReferencePath);engine.GetSpeech("Hello",1.1,"");Check(engine.Calls==6,"Transcript, device, voice, speed and changed reference invalidate cached audio");for(int i=0;i<40;i++)engine.GetSpeech("unique"+i,1,"");int before=engine.Calls;engine.GetSpeech("unique0",1,"");Check(engine.Calls==before+1,"Bounded cache evicts old entries");
  engine=new FakeSpeech{Root=root,Seconds=.3,PreviewCache=new SpeechCache(),VoiceName="Measured"};var cues=Enumerable.Range(0,20).Select(i=>new Cue{Id=i+1,Start=i*3.45,End=i*3.45+3.3,Text="Sentence "+i+"."}).ToList();original=Scripts.ToSrt(cues);string report=VoiceRhythm.Measure(cues,engine,new RenderOptions(),Path.Combine(dir,"measure"),(p,m)=>{});Check(engine.Calls==5&&report.Contains("5 khối"),"Rhythm check measures five representative cues");Check(Scripts.ToSrt(cues)==original,"Rhythm check never changes source words or timecodes");for(int i=0;i<20;i++)Punctuation.Generate(engine,cues[i].Text,1,new RenderOptions(),"");Check(engine.Calls==20,"Rendering reuses exactly the five measured cues");
  foreach(string name in new[]{"CAPCUT_V15_4_US_VOICE_SAMPLE.wav","EXCITER RENDER V15.wav"}){string input=Path.Combine(root,"upload",name),output=Path.Combine(dir,name);long frames=FinalAudio.PcmFrames(input);double inputLevel=FinalAudio.Measure(root,input,No).Integrated;FinalAudio.Normalize(root,input,output,frames,-18,No,null);var stats=FinalAudio.Measure(root,output,No);Check(Math.Abs(stats.Integrated+18)<.6,"Actual "+name+" normalized near -18 LUFS ("+stats.Integrated+")");Check(stats.TruePeak<=-.85&&FinalAudio.PcmFrames(output)==frames,"Actual "+name+" preserves exact samples and safe true peak ("+stats.TruePeak+")");Check(stats.Integrated-inputLevel>5,"Actual quiet rendered voice becomes audibly louder");Console.WriteLine("MEASURE "+name+" input="+inputLevel+" output="+stats.Integrated+" peak="+stats.TruePeak+" frames="+frames);}
  string tone=Path.Combine(dir,"tone.wav"),norm=Path.Combine(dir,"norm.wav");Tone(10).Write(tone);FinalAudio.Normalize(root,tone,norm,240000,-24,No,null);Check(Math.Abs(FinalAudio.Measure(root,norm,No).Integrated+24)<.4,"Custom loudness target -24 LUFS is honored");var normalized=Wave.Read(norm);int crossings=0;for(int i=24001;i<216000;i++)if(normalized.Samples[i-1]<0&&normalized.Samples[i]>=0)crossings++;Check(Math.Abs(crossings/8.0-220)<1,"Loudness normalization preserves 220 Hz pitch");string silent=Path.Combine(dir,"silent.wav"),silentOut=Path.Combine(dir,"silent-out.wav");new Wave{Rate=24000,Samples=new short[240000]}.Write(silent);FinalAudio.Normalize(root,silent,silentOut,240000,-18,No,null);Check(File.ReadAllBytes(silent).SequenceEqual(File.ReadAllBytes(silentOut)),"Silent WAV passes safely without invalid gain");
  File.WriteAllText(Path.Combine(dir,"existing.wav"),"KEEP");Reject(()=>FinalAudio.Normalize(root,tone,Path.Combine(dir,"existing.wav"),240000,-18,No,null),"Loudness processor rejects existing intermediate output");Check(File.ReadAllText(Path.Combine(dir,"existing.wav"))=="KEEP","Existing output preserved on normalization rejection");Reject(()=>FinalAudio.Normalize(root,tone,Path.Combine(dir,"cancel.wav"),240000,-18,()=>true,null),"Loudness scan honors cancellation");Check(!File.Exists(Path.Combine(dir,"cancel.wav")),"Cancelled loudness scan leaves no output");
  engine=new FakeSpeech{Root=root,Seconds=1};cue=new Cue{Id=1,Start=0,End=2,Text="Fail final stage."};string keep=Path.Combine(dir,"keep.wav");File.WriteAllText(keep,"KEEP");Environment.SetEnvironmentVariable("V15_FFMPEG","/missing/ffmpeg");Reject(()=>Renderer.Render(new List<Cue>{cue},engine,new RenderOptions{SlowShort=false,NormalizeLoudness=true,Breathing=BreathMode.None},keep,(p,m)=>{}),"Final loudness failure rejects entire render");Environment.SetEnvironmentVariable("V15_FFMPEG",null);Check(File.ReadAllText(keep)=="KEEP"&&!Directory.GetFiles(dir,"*.tmp").Any(),"Failed final stage preserves existing WAV and removes partial output");
  string video=Path.Combine(root,"upload","VANZAI.mp4"),sample=Path.Combine(dir,"vanzai.wav");var selected=UserVoices.Import(root,video,sample,4,10,No);var sampleStats=FinalAudio.Measure(root,sample,No);Check(selected.Samples.Length==240000&&selected.Rate==24000,"Real VANZAI MP4 excerpt is exact 10-second mono 24 kHz WAV");Check(sampleStats.TruePeak<=-.85&&selected.Samples.All(x=>Math.Abs((int)x)<32767),"MP4 float decoding prevents AAC overshoot clipping (peak "+sampleStats.TruePeak+")");
  string direct=Path.Combine(dir,"original.wav");AudioProcess.Run(root,"-v error -y -ss 4 -i "+KokoroEngine.Q(video)+" -t 10 -vn -ac 1 -ar 24000 -af volume=-6dB -c:a pcm_s16le "+KokoroEngine.Q(direct),No);var source=Wave.Read(direct);double xy=0,xx=0,yy=0;for(int i=0;i<selected.Samples.Length;i++){xy+=(double)source.Samples[i]*selected.Samples[i];xx+=(double)source.Samples[i]*source.Samples[i];yy+=(double)selected.Samples[i]*selected.Samples[i];}Check(xy/Math.Sqrt(xx*yy)>.9999,"MP4 import preserves the original voice waveform and timing");
  string dst=Path.Combine(dir,"preserved.wav");ImportReject(video,dst,132,10,"Truncated selected interval rejected");ImportReject(video,dst,Double.NaN,10,"Invalid sample offset rejected");ImportReject(video,dst,0,21,"Oversized sample length rejected");ImportReject(silent,dst,0,10,"Silent sample rejected");File.WriteAllText(dst,"KEEP");Reject(()=>UserVoices.Import(root,video,dst,4,10,()=>true),"Sample import honors cancellation");Check(File.ReadAllText(dst)=="KEEP"&&!Directory.GetFiles(dir,".v15_sample_*").Any(),"Import cancellation preserves existing reference and cleans temporary audio");
  string noAudio=Path.Combine(dir,"noaudio.mp4");AudioProcess.Run(root,"-v error -y -f lavfi -i color=c=black:s=16x16:d=7 -an -c:v mpeg4 "+KokoroEngine.Q(noAudio),No);ImportReject(noAudio,dst,0,6,"MP4 without audio rejected");
  var replace=UserVoices.Import(root,video,dst,4,10,No);Check(replace.Samples.Length==240000&&FinalAudio.PcmFrames(dst)==240000,"Successful sample replaces an existing target only after validation");
  engine=new FakeSpeech{Root=root,Seconds=.6};cue=new Cue{Id=1,Start=0,End=3.3,Text="Slow custom."};Renderer.Render(new List<Cue>{cue},engine,new RenderOptions{BaseSpeed=1.3,MinSpeed=.5,MaxSpeed=1.6,SlowShort=true,Breathing=BreathMode.None},Path.Combine(dir,"slow-range.wav"),(p,m)=>{});Check(cue.Speed==.5,"Explicit low speed bound supports chained pitch-preserving tempo filters");
  engine=new FakeSpeech{Root=root,Seconds=1};cue=new Cue{Id=1,Start=0,End=2,Text="Cancel final."};Reject(()=>Renderer.Render(new List<Cue>{cue},engine,new RenderOptions{SlowShort=false,NormalizeLoudness=true,Breathing=BreathMode.None},keep,(p,m)=>{if(p==97)engine.Cancelled=true;}),"Cancellation during final loudness stage stops publication");Check(File.ReadAllText(keep)=="KEEP"&&!Directory.GetFiles(dir,"*.tmp").Any(),"Cancelled final stage preserves previous output");
  engine=new FakeSpeech{Root=root,Seconds=1};var finalCues=new List<Cue>{new Cue{Id=1,Start=0,End=2,Text="First."},new Cue{Id=2,Start=2.15,End=4.15,Text="Second."}};original=Scripts.ToSrt(finalCues);string final=Renderer.Render(finalCues,engine,new RenderOptions{NormalizeLoudness=true,SlowShort=false,Breathing=BreathMode.None},Path.Combine(dir,"normalized-render.wav"),(p,m)=>{});Check(FinalAudio.PcmFrames(final)==99600&&Scripts.ToSrt(finalCues)==original,"Complete render with loudness processing preserves source timeline and exact master frame count");
  Check(Math.Abs(FinalAudio.Measure(root,final,No).Integrated+18)<.6,"Complete render applies selected loudness target at final stage");
  var old=VoiceSettings.From(new XElement("settings",new XAttribute("speed","0.8")));Check(old.Normalize&&old.GentleFit&&old.MinSpeed<=old.Speed,"Older sessions receive compatible quality defaults");var settings=new VoiceSettings{Normalize=false,TargetLufs=-20,GentleFit=false,MinSpeed=.7};var restored=VoiceSettings.From(settings.Xml());Check(!restored.Normalize&&restored.TargetLufs==-20&&!restored.GentleFit&&restored.MinSpeed==.7,"All new quality choices survive preset serialization");
  Console.WriteLine("TOTAL UPDATE 1.4.5 "+count+" passed. Artifacts: "+dir);
 }
}
